schema.example:
type Query {
  feed: [Post]
  me: Account
}

interface Timestamped { createdAt: String! }
interface Archivable { archivedAt: String }

type Post implements Timestamped {
  id: ID!
  body: String!
  legacyTitle: String @deprecated
  author: Author
}

type Account { id: ID! }
type Orphan { id: ID! }
